  $('#app').innerHTML=`<header class="game-header"><button class="kingdom-brand" data-view="profile" title="Hồ sơ người chơi"><span class="hud-avatar ${state.account.equipped.frame} ${titleFrameClass(state)}">${portrait(state.account.avatar)}</span><span class="lord-level">${playerProgress(state).level}</span><div><b>${escapeAccountText(state.account.name)}</b><small id="power-value">⚔ ${fmt(state.levels.hall*1300+state.troops*10+state.owned.length*120)}</small></div></button><div class="resource-strip">${[['food','♧','Thức ăn'],['wood','♠','Gỗ'],['stone','◆','Đá'],['coins','◈','Ngọc']].map(([id,icon,label])=>`<div class="resource resource-${id}"><span>${icon}</span><div><small>${label}</small><b id="res-${id}">${fmt(id==='coins'?state.coins:state.resources[id])}</b></div></div>`).join('')}<div class="resource resource-gold"><span>●</span><div><small>Vàng</small><b id="gold-value">${fmt(state.commerce.gold)}</b></div></div><div class="resource population-resource"><span>♙</span><div><small>Dân rảnh / Tổng</small><b id="population-value">${populationAvailable(state)} / ${populationCapacity(state)}</b></div></div></div><button class="hud-mail" data-view="mail" title="Hộp thư chiến tuyến">✉<small id="mail-unread">${state.mailbox.reports.filter(r=>r.mode==='bot'&&!r.read).length+state.mailbox.notices.filter(n=>!n.read).length+state.mailbox.parcels.filter(p=>!p.claimed).length}</small></button><button class="audio-toggle-button" data-audio-enable title="Enable or disable audio">${state.feedback.audioEnabled?'♫':'♪'}</button><button class="fullscreen-button" data-fullscreen title="Toàn màn hình">⛶</button></header><nav class="game-nav" aria-label="Chức năng game">${navigation.map(([id,icon,title])=>`<button data-view="${id}" class="${(view===id||(view==='character'&&id==='heroes'))?'current':''}">${navArt(id)}<small>${title}</small></button>`).join('')}</nav><main class="game-content ${mapMode?'map-content':'scroll-content'}">${mapMode?mapPage():accountTabs(view)+({strongholds:()=>strongholdPage(state,selectedStronghold),boss:()=>worldBossPage(state,worldRaid,portrait),titles:()=>titleCollectionPage(state,titleTab),settings:()=>settingsPage(state,link),auction:()=>auctionPage(state,marketTab,marketFilters,marketSelection,link),room:()=>roomPage(state,link,roomTab,null,portrait,tradeSelection,tradePage,tradeRecipient),relocation:()=>relocationPage(state,destinationX,destinationY),exchange:()=>exchangePage(state),squads:()=>squadOverviewPage(state,portrait),allocation:()=>troopAllocationPage(state,portrait),mail:()=>mailTab==='reports'&&!mailDetailed?battleComparisonPage(state,portrait,selectedMailId,reportUnitPage):'<button data-report-summary>← Battle Overview</button>'+mailPage({...state,mailbox:{...state.mailbox,reports:state.mailbox.reports.filter(r=>r.mode==='bot')}},portrait,selectedMailId,mailTab),inheritance:()=>inheritancePage(state),runes:()=>runeIconPage(state),quests:()=>missionPage(state,missionTab,missionPageIndex),skins:()=>skinsPage(state),production:()=>productionPage(state,selectedBuilding,productionBatches),medical:()=>medicalPage(state,medicalType,medicalAmount),army:()=>technologyPage(state,technologyTab),campaign:()=>renderCampaignGallery(state,campaignChapter),longs:()=>longSanctuaryPage(state),shop:()=>shopTab==='commands'?commandShopPage(state):shopTab==='exchange'?exchangePage(state):shopTab==='boxes'?shopPage(state):fragmentShopPage(state,shopTab),profile:()=>profilePage(state,portrait),vip:()=>vipPage(state,portrait,vipPreview),pets:()=>renderPetGallery(state,petResults),bag:()=>renderBagGallery(state,portrait,bagTab,bagPageIndex),'gear-gacha':()=>renderEquipmentGacha(state,gearResults),heroes:heroesPage,character:characterPage,summon:summonPage,journal:()=>storyJournalPage(state),saves:()=>saveManagementPage(state),help:helpPage,building:buildingInterior})[view]()}</main>${state.account.realm.faction?'':realmSetup(state,realmDraft)}`;
  if(view==='heroes'&&$('.recommendation-panel')){const target=currentAdvisorTarget();advisorSuggestions=new FormationAdvisor().suggest(state,target);$('.recommendation-panel').innerHTML=advisorPanel(state,target,advisorSuggestions);requestAnimationFrame(()=>drawFormationLinks($('.formation-board'),state,effectiveFormationPower(state,state.formation,target.waves).synergy));}
  setEnglishPlayerNames([state.account.name,...Object.values(link?.room?.players||{}).map(p=>p.state.account.name)]);applyEnglishUI($('#app'));
  fitGameResolution();
  if($('.hero-carousel')){const carousel=$('.hero-carousel');carousel.scrollLeft=carouselPosition;carousel.scrollTop=carouselTop;bindHeroCarouselGestures(carousel);carousel.addEventListener('wheel',e=>{e.preventDefault();if(matchMedia('(pointer:coarse)').matches)carousel.scrollTop+=e.deltaY;else carousel.scrollLeft+=Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY;},{passive:false});}

  if($('.market-content'))$('.market-content').scrollTop=marketScroll;if(view==='auction'&&marketBid!==null)$('#app').insertAdjacentHTML('beforeend',auctionBidDialog(state,marketBid));
  if($('#peer-map'))mapView=mountPeerMap($('#peer-map'),()=>link.room,(x,y)=>{$('#peer-move-x').value=Math.max(150,Math.min(950,x));$('#peer-move-y').value=Math.max(100,Math.min(650,y));});
  if(state.titles.pending.length&&!descriptionKey&&!worldRaid?.result){const id=state.titles.pending[0],t=titleById[id];$('#app').insertAdjacentHTML('beforeend',`<div class="title-unlock-notice title-frame rarity-${t.rarity}"><b>Title Unlocked: ${t.name}</b><button data-title-unlock-equip="${id}">Equip Now</button><button data-title-unlock-later>Later</button></div>`);}
  if(state.battle&&!state.battle.winner&&view==='combat')$('#app').insertAdjacentHTML('beforeend','<button class="skip-battle-button" data-skip-battle>Skip Battle · Calculate Result</button>');if(worldRaid&&!worldRaid.result&&view==='boss')$('#app').insertAdjacentHTML('beforeend','<button class="skip-battle-button" data-skip-battle>Skip Raid · Calculate Result</button>');
  if(summonReveal){$('#app').insertAdjacentHTML('beforeend',summonRevealScene());applyEnglishUI($('#app'));}
  if(descriptionKey)$('#app').insertAdjacentHTML('beforeend',renderDescription(state,descriptionKey,portrait,{hero:heroFocus,slot:pickedGearSlot},descriptionPage,descriptionFallback));
