let previous=performance.now(),economyElapsed=0,idleElapsed=0,hudElapsed=0,saveElapsed=0;
setInterval(()=>{const now=performance.now(),dt=Math.max(0,Math.min(.5,(now-previous)/1000));previous=now;lastSimulationStamp=now;economyElapsed+=dt;idleElapsed+=dt;hudElapsed+=dt;saveElapsed+=dt;
 const beforeWinner=state.battle?.winner,beforeStage=state.battle?.stage,beforeRegion=state.worldAI.expedition?.stage,beforeMarch=state.march?.stage;
 feedback.observeState(state,{level:playerProgress(state).level});feedback.consume(view==='boss'?worldRaid?.battle:state.battle);if(link?.active||resolvingBattle)return;
 if(view==='boss'&&!worldRaid){bossRefresh+=dt;if(bossRefresh>=1){refreshBossLobby(state);bossRefresh=0;}}
 if(worldRaid&&!worldRaid.result){bossBackend.tick(state,worldRaid,dt*speed);bossRefresh+=dt;if(view==='boss'&&bossRefresh>=.25){refreshBossUI(state,worldRaid);bossRefresh=0;}if(worldRaid.result){save();if(view==='boss')render();}}
 if(economyElapsed>=1){state=localAuctionBackend.tick(relocationTick(economyTick(state)));economyElapsed=0;}
 if(state.campaignBattle||state.battle?.mode==='campaign')state=campaignTick(state,dt*speed);if(state.battle?.mode==='secret')state=secretBattleTick(state,dt*speed);else if(state.march)state=worldTick(state,dt*speed);
 if(deployments(state).length){state=worldSystemsTick(state,document.visibilityState==='visible'?dt:0,dt*speed);idleElapsed=0;}else if(idleElapsed>=1){state=worldSystemsTick(state,document.visibilityState==='visible'?idleElapsed:0,idleElapsed*speed);idleElapsed=0;}
 let sceneChanged=false;if(state.battle?.mode==='campaign'&&state.battle.stage!==beforeStage&&['combat','campaign'].includes(view)){view='combat';sceneChanged=true;}if(beforeMarch!=='combat'&&state.march?.stage==='combat'&&view==='world'){view='combat';drawerOpen=false;sceneChanged=true;}
 if(sceneChanged){resultDismissed=false;render();}else if(hudElapsed>=.25){refreshLive(false);hudElapsed=0;}
 if(state.strongholds.queued&&!activeDeployment(state,state.strongholds.queued.squadId)){const q=state.strongholds.queued,old=state.squads.active;state.strongholds.queued=null;try{const target=state.strongholds.sites.filter(n=>n.typeId===q.typeId&&n.level===q.level&&n.status==='alive'&&n.cityId===activeWorldCity(state)).sort((a,b)=>Math.hypot(a.x,a.y-420)-Math.hypot(b.x,b.y-420))[0];if(!target)throw new Error('No same-level target is currently available.');state=activateSquad(state,q.squadId);state=new StrongholdManager().launch(state,target.id);state=activateSquad(state,old);notify('The next stronghold march has started.');}catch(error){state=activateSquad(state,old);notify(error.message);}save();}
 if(!beforeWinner&&state.battle?.winner||saveElapsed>=5){save();saveElapsed=0;}
},100);
