function summonRevealScene(){const list=summonReveal,counts=Object.fromEntries(gradeOrder.map(g=>[g,list.filter(h=>h.grade===g).length]));return `<section class="summon-reveal summon-batch" role="dialog" aria-modal="true" aria-label="${list.length} Summon Results"><div class="pixel-tv-flash"></div><header><div><h1>The Mandate Has Answered · ${list.length} Cards</h1><span>All rewards are already stored. Scroll to inspect your heroes.</span><p class="summon-rarity-summary">${gradeOrder.filter(g=>counts[g]).map(g=>`<b style="color:${gradeColors[g]}">${g} ×${counts[g]}</b>`).join(' ')}</p></div><button data-summon-skip>Continue</button></header><div class="summon-card-grid">${list.map((h,index)=>`<article class="summon-card grade-${h.grade}" style="--card-color:${gradeColors[h.grade]};--reveal-delay:${Math.min(index,9)*35}ms">${portrait(h.id)}<b>${h.name}</b><strong>${h.grade}</strong><small>${h.duplicate?'+'+(shardYield[h.grade]||0)+' Shards':'New Hero'}</small></article>`).join('')}</div></section>`;}


document.addEventListener('input',e=>{if(e.target.id!=='healing-amount')return;const n=Number(e.target.value),valid=Number.isInteger(n)&&n>=1&&n<=state.medical.wounded[medicalType],button=document.querySelector('[data-start-healing]');if(!valid){button.disabled=true;return;}medicalAmount=n;const q=healingQuote(state,medicalType,n);document.querySelector('[data-healing-food]').textContent=q.food;document.querySelector('[data-healing-wood]').textContent=q.wood;document.querySelector('[data-healing-duration]').textContent=q.seconds;button.disabled=state.resources.food<q.food||state.resources.wood<q.wood;});

