document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-title-tab')){titleTab=b.dataset.titleTab;render();}else if(b.hasAttribute('data-title-equip')){titleManager.equip(state,b.dataset.titleEquip);save();render();}else if(b.hasAttribute('data-title-frame')){titleManager.frame(state,b.dataset.titleFrame);save();render();}else if(b.hasAttribute('data-title-display')){const id=b.dataset.titleDisplay,ids=state.titles.display;titleManager.display(state,ids.includes(id)?ids.filter(k=>k!==id):[...ids,id]);save();render();}});

document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;try{if(b.dataset.bossEnter||b.dataset.bossPractice){worldRaid=bossBackend.start(state,b.dataset.bossEnter||b.dataset.bossPractice,{practice:!!b.dataset.bossPractice});view='boss';save();render();}else if(b.hasAttribute('data-boss-dodge')){bossBackend.dodge(worldRaid);render();}else if(b.hasAttribute('data-boss-leave')){bossBackend.retreat(state,worldRaid);worldRaid=null;save();render();}else if(b.hasAttribute('data-boss-inbox')||b.hasAttribute('data-boss-sell')){if(b.hasAttribute('data-boss-sell')){const reward=worldRaid?.rewards.find(p=>p.asset?.kind==='bag'&&exclusiveById[p.asset.id]);if(reward){state=localAuctionBackend.claim(state,reward.id);marketSelection={...reward.asset};save();}marketTab='sell';}else marketTab='inbox';view='auction';render();}}catch(error){notify(error.message);}});

