document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-title-unlock-equip')||b.hasAttribute('data-title-unlock-later')){if(b.dataset.titleUnlockEquip)titleManager.equip(state,b.dataset.titleUnlockEquip);state.titles.pending.shift();save();render();}});

document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;try{if(b.dataset.advisorTarget||b.dataset.advisorBoss){advisorTargetId=b.dataset.advisorTarget||b.dataset.advisorBoss;view='heroes';formationHelp=true;render();}else if(b.dataset.advisorApply!==undefined){assertIdle();advisorUndo=[...state.formation];state=applyFormationTemplate(state,advisorSuggestions[Number(b.dataset.advisorApply)].formation);save();render();}else if(b.hasAttribute('data-advisor-undo')&&advisorUndo){assertIdle();state=applyFormationTemplate(state,advisorUndo);advisorUndo=null;save();render();}else if(b.hasAttribute('data-template-save')){state=saveFormationTemplate(state,$('#formation-template-name').value);save();render();}else if(b.dataset.templateLoad!==undefined){assertIdle();advisorUndo=[...state.formation];state=applyFormationTemplate(state,state.savedFormations.entries[Number(b.dataset.templateLoad)].slots);save();render();}else if(b.dataset.templateDelete!==undefined){state.savedFormations.entries.splice(Number(b.dataset.templateDelete),1);save();render();}}catch(error){notify(error.message);}});

feedback.mount(key=>{const element=document.querySelector('[data-feedback-key="'+CSS.escape(key||'')+'"]');if(element){const r=element.getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/3};}const c=document.querySelector('#world-map'),p=c?.feedbackPositions?.[key];if(c&&p){const r=c.getBoundingClientRect();if(matchMedia('(pointer:coarse)').matches&&innerHeight>innerWidth)return{x:r.right-p.y/c.clientHeight*r.width,y:r.top+p.x/c.clientWidth*r.height};return{x:r.left+p.x/c.clientWidth*r.width,y:r.top+p.y/c.clientHeight*r.height};}return{x:innerWidth/2,y:innerHeight*.4};});
document.addEventListener('pointerdown',event=>{const button=event.target.closest('button');if(button&&!button.disabled)feedback.emit('ui_click',{x:event.clientX,y:event.clientY});},{passive:true});
document.addEventListener('change',event=>{const el=event.target,key=el.dataset.feedbackSetting;if(!key)return;state.feedback[key]=el.type==='checkbox'?el.checked:el.type==='range'||key==='battleSpeed'?Number(el.value):el.value;speed=state.feedback.battleSpeed;feedback.speed=speed;feedback.configure(state.feedback);save();document.body.classList.toggle('reduce-motion',state.feedback.reduceMotion);});
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-audio-enable')){state.feedback.audioEnabled=!state.feedback.audioEnabled;feedback.configure(state.feedback);await feedback.unlock();feedback.emit('ui_click');save();render();}else if(b.hasAttribute('data-skip-battle'))await skipCurrentBattle();});
async function skipCurrentBattle(){if(resolvingBattle||link?.active)return;resolvingBattle=true;const settings={...state.feedback};feedback.configure({...settings,effectsLevel:'off'});try{notify('Resolving battle using the existing combat rules…');if(view==='boss'&&worldRaid){for(let n=0;n<6000&&!worldRaid.result;n++){bossBackend.tick(state,worldRaid,.5);if(n%100===0)await new Promise(requestAnimationFrame);}}else{const mode=state.battle?.mode,squadId=state.battle?.squadId;if(mode==='campaign'){state.campaign.autoAdvance=false;state.campaign.autoReplay=false;}for(let n=0;n<600;n++){if(mode==='campaign'){state=campaignTick(state,5);if(state.campaignBattle?.winner)break;}else if(mode==='secret'){state=secretBattleTick(state,5);if(state.battle?.winner)break;}else if(['bot','hunt','stronghold'].includes(mode)){state=worldSystemsTick(state,0,5);const job=activeDeployment(state,squadId);if(!job||job.stage!=='combat')break;}else{state=worldTick(state,5);if(state.battle?.winner)break;}if(n%25===0)await new Promise(requestAnimationFrame);}}save();}catch(error){notify(error.message);}finally{resolvingBattle=false;feedback.configure(settings);feedback.consume(view==='boss'?worldRaid?.battle:state.battle);render();}}

document.addEventListener('click',event=>{const b=event.target.closest('[data-stronghold-next]');if(!b)return;const site=state.strongholds.sites.find(n=>n.id===b.dataset.strongholdNext);if(site){state.strongholds.queued={squadId:state.battle?.squadId??state.squads.active,typeId:site.typeId,level:site.level};save();notify('Next march queued. Troops return first; March Qi is charged on dispatch.');}});
